"""Serializable sensor model parameters."""


class _SingleCamHandeyeConfigRequired(TypedDict):
    """The keys of `SingleCamHandeyeConfig` that every payload has."""

    handeye_init: HandeyeInitConfig
    """Hand-eye linear-initialization stage settings (Tsai-Lenz DLT)."""

    intrinsics: IntrinsicsInitConfig
    """Per-camera linear-initialization stage settings. `fix_tangential`
    defaults to `true` for a Scheimpflug sensor and `false` otherwise.
    """

    robot_poses: RobotPoseConfig
    """Robot-pose refinement settings for the hand-eye bundle adjustment."""

    solver: SolverConfig
    """Non-linear solve stage settings."""


class SingleCamHandeyeConfig(_SingleCamHandeyeConfigRequired, total=False):
    """Configuration for single-camera hand-eye calibration.

    Grouped by stage: per-camera linear init, the camera model, hand-eye
    linear init, non-linear solve, and robot-pose refinement each live in
    their own shared sub-struct. Every group's own `Default` is the plain
    workspace default (no per-problem override is needed here, unlike
    `PlanarIntrinsicsConfig`'s iteration cap).
    """

    camera: CameraConfig
    """The camera model and the parameters its solves (the intrinsics stage
    and the hand-eye bundle adjustment) hold fixed. Any distortion kind
    with an identity sensor; a Scheimpflug sensor needs a distortion
    model. A tilted sensor's intrinsics stage runs a multi-start tilt
    sweep; seed its tilt through the intrinsics manual init.
    """


class _SingleCamHandeyeExportRequired(TypedDict):
    """The keys of `SingleCamHandeyeExport` that every payload has."""

    base_se3_target: Iso3 | None
    """Eye-in-hand: base_se3_target (T_B_T).

    `None` for EyeToHand mode.
    """

    camera: CameraParams
    """Calibrated camera, in the configured model."""

    camera_se3_base: Iso3 | None
    """Eye-to-hand: camera_se3_base (T_C_B).

    `None` for EyeInHand mode.
    """

    gripper_se3_camera: Iso3 | None
    """Eye-in-hand: gripper_se3_camera (T_G_C).

    `None` for EyeToHand mode.
    """

    gripper_se3_target: Iso3 | None
    """Eye-to-hand: gripper_se3_target (T_G_T).

    `None` for EyeInHand mode.
    """

    handeye_mode: HandeyeMode
    """Hand-eye mode used to interpret the transforms."""

    kind: ExportKind
    """Export-type discriminator — always `ExportKind::SingleCamHandeye`."""

    mean_reproj_error: float
    """Mean reprojection error (pixels)."""

    per_cam_reproj_errors: list[float]
    """Per-camera reprojection errors (pixels). Single element for single-camera."""

    per_feature_residuals: PerFeatureResiduals
    """Per-feature reprojection residuals. Single-camera, target
    only. Per-view `cam_se3_target` is derived from the handeye chain
    (see `handeye_observer_se3_target`).
    """

    robot_deltas: list[tuple[float, float, float, float, float, float] | list[float]] | None
    """Per-view robot pose deltas (se(3) tangent: [rx, ry, rz, tx, ty, tz]).
    Only present if robot refinement was enabled.
    """

    uncertainty: Uncertainty
    """Covariance of the calibrated parameters: `fx ± σ`, correlations, and
    the noise level the residuals imply.
    """


class SingleCamHandeyeExport(_SingleCamHandeyeExportRequired, total=False):
    """Export format for single-camera hand-eye calibration."""

    image_manifest: ImageManifest | None
    """Optional pointer to the source images behind this export. When
    populated, downstream viewers (the diagnose UI) can locate the
    source image for each view. `None` means "no images shipped";
    the calibration pipeline never reads this field.
    """


class SingleCamHandeyeInput(TypedDict):
    """Input for single-camera hand-eye calibration."""

    views: list[SingleCamHandeyeView]
    """Per-view observations with robot poses."""


class SingleCamHandeyeView(TypedDict):
    """Single-camera observation view with attached metadata."""

    meta: HandeyeMeta
    """Arbitrary metadata payload associated with the view."""

    obs: CorrespondenceView
    """2D-3D correspondences observed in this view."""


class SolveReport(TypedDict):
    """Summary of backend solve outcome."""

    final_cost: float
    """The objective at the solution: `½ Σᵢ ρᵢ(‖rᵢ‖²)` over the residual
    blocks, where `ρᵢ` is the block's robust loss (`ρ(s) = s` without
    one) — so `½‖r‖²` for a plain least-squares problem.
    """

    num_iters: int
    """Number of outer solver iterations executed."""


SolverBackend: TypeAlias = Literal["tiny_solver", "factrs"]
"""Which engine linearizes the problem.

Both run the same Levenberg–Marquardt loop over the same residual
kernels and reach the same minimizer; they differ in how they build the
Jacobian and how they fold in a robust loss.

- ``"tiny_solver"``: `tiny-solver`: dynamic-size forward-mode dual numbers; a robust loss
  enters through the Triggs correction (second-order exact).
- ``"factrs"``: `factrs`: static-size forward-mode dual numbers; a robust loss enters
  through iterative reweighting (each block scaled by `√ρ′`).
"""


class _SolverConfigRequired(TypedDict):
    """The keys of `SolverConfig` that every payload has."""

    max_iters: int
    """Maximum iterations for the non-linear optimizer."""

    robust_loss: RobustLoss
    """Robust loss function for outlier handling."""

    verbosity: int
    """Verbosity level (0 = silent, 1 = summary, 2+ = detailed)."""


class SolverConfig(_SolverConfigRequired, total=False):
    """Non-linear solve stage options shared across problem types.

    `max_iters` has no single workspace-wide default — problems override it
    per solve-stage cost. Documented per-problem defaults: 50 standard; 120
    for planar intrinsics (sized for a tilted sensor's tilt valley; the
    solver stops at convergence, so the cap only bounds runs that do not
    converge); 30 for a warm-started joint
    rig+hand-eye+laser polish; 200 for the rig-laserline frozen-geometry
    stage (cheap 1-DOF-per-view problem). This struct's own `Default` is
    50 — the plain value used by problems with no reason to deviate.
    """

    backend: SolverBackend
    """Engine that linearizes the problem for the Levenberg–Marquardt loop.
    Both reach the same minimizer; see `SolverBackend`.
    """


class TargetFeatureResidual(TypedDict):
    """Reprojection record for a single target feature in a single view."""

    camera: int
    """Camera index. `0` for single-camera problem types."""

    error_px: float | None
    """Euclidean pixel distance `|projected - observed|`.
    `None` iff `projected_px` is `None`.
    """

    feature: int
    """Feature index within the view's `points_3d`."""

    observed_px: tuple[float, float] | list[float]
    """Observed pixel coordinate."""

    pose: int
    """Pose / view index in the input dataset."""

    projected_px: tuple[float, float] | list[float] | None
    """Projected pixel using the calibrated camera + recovered pose.
    `None` when projection diverges (point behind camera, distortion failure).
    """

    target_xyz_m: tuple[float, float, float] | list[float]
    """3D point in target / world frame (meters)."""


class TargetSpec_Charuco(TypedDict):
    """ChArUco board. Marker IDs and dictionary live here so detection
    is fully deterministic from the manifest.
    """

    cols: int
    """Number of squares along the cols axis."""

    dictionary: str
    """ArUco dictionary identifier (e.g. `"DICT_4X4_50"`). The
    detector validates this against the supported set.
    """

    kind: Literal["charuco"]
    marker_size_m: float
    """Edge length of an embedded marker in metres."""

    rows: int
    """Number of squares along the rows axis (full grid, not
    interior corners).
    """

    square_size_m: float
    """Edge length of one square in metres."""


class TargetSpec_Chessboard(TypedDict):
    """Standard checkerboard. Counts are interior corners
    (i.e. `9x6` ⇒ a 10×7 black-and-white square grid).
    """

    cols: int
    """Number of interior corners along the cols axis."""

    kind: Literal["chessboard"]
    rows: int
    """Number of interior corners along the rows axis."""

    square_size_m: float
    """Edge length of one square in metres."""


class TargetSpec_Puzzleboard(TypedDict):
    """Puzzleboard target: a self-identifying chessboard. The layout name
    carries the board's dimensions, so the manifest fully determines
    detection.
    """

    cell_size_m: float
    """Edge length of one cell in metres."""

    kind: Literal["puzzleboard"]
    layout: str
    """Board dimensions as `puzzle_<rows>x<cols>` (e.g.
    `"puzzle_12x12"`; the `puzzle_` prefix is optional).
    """


class TargetSpec_Ringgrid(TypedDict):
    """Coded ring-grid target (the `ringgrid` crate). The board is a
    hex-lattice of self-identifying ring markers; its geometry mirrors
    `ringgrid::BoardLayout` so the manifest fully determines detection.
    """

    kind: Literal["ringgrid"]
    long_row_cols: int
    """Number of columns in the longest (even-indexed) row. Shorter
    rows are derived by the hex-lattice layout.
    """

    marker_inner_radius_m: float
    """Inner ring radius in metres."""

    marker_outer_radius_m: float
    """Outer ring radius in metres."""

    marker_ring_width_m: float
    """Width of each ring band in metres."""

    pitch_m: float
    """Center-to-center spacing between adjacent markers in metres."""

    rows: int
    """Number of marker rows."""


TargetSpec: TypeAlias = (
    TargetSpec_Chessboard
    | TargetSpec_Charuco
    | TargetSpec_Puzzleboard
    | TargetSpec_Ringgrid
)
"""Calibration-target metadata. Tagged on `kind`."""


Topology: TypeAlias = Literal[
    "planar_intrinsics",
    "single_cam_handeye",
    "laserline_device",
    "rig_extrinsics",
    "rig_handeye",
    "rig_handeye_laserline",
    "rig_laserline_device",
]
"""Calibration topology — selects the problem-type dispatch.

A topology describes the data (how many cameras, robot poses, laser
images), not the camera model: a tilted (Scheimpflug) single camera is a
`planar_intrinsics` dataset whose calibration config names the sensor.

- ``"planar_intrinsics"``: Single camera, planar target — `PlanarIntrinsicsProblem` (any camera
  model, including a tilted sensor).
- ``"single_cam_handeye"``: Single camera mounted on a robot — `SingleCamHandeyeProblem`.
- ``"laserline_device"``: Camera + laser plane — `LaserlineDeviceProblem`.
- ``"rig_extrinsics"``: Multi-camera rig, target only — `RigExtrinsicsProblem`.
- ``"rig_handeye"``: Multi-camera rig + robot — `RigHandeyeProblem`.
- ``"rig_handeye_laserline"``: Multi-camera rig + robot + laser planes — joint hand-eye/laser BA.
- ``"rig_laserline_device"``: Multi-camera rig + laser planes — `RigLaserlineDeviceProblem`.
"""


TransformConvention: TypeAlias = Literal[
    "t_base_tcp",
    "t_tcp_base",
    "t_world_tcp",
    "t_tcp_world",
]
"""Which transform a pose row encodes.

- ``"t_base_tcp"``: `T_base_tcp` — gripper pose in the robot base frame (KUKA, UR
  default).
- ``"t_tcp_base"``: `T_tcp_base` — base pose in the gripper frame (some ABB exports).
- ``"t_world_tcp"``: `T_world_tcp` — gripper pose in a fixed world frame (less
  common; some lab-frame setups).
- ``"t_tcp_world"``: `T_tcp_world` — world pose in the gripper frame.
"""


TranslationUnits: TypeAlias = Literal["m", "mm"]
"""Translation units in the file.

- ``"m"``: Metres (SI, preferred).
- ``"mm"``: Millimetres (some ABB / Fanuc exports).
"""


class _Uncertainty_AvailableRequired(TypedDict):
    """The keys of `Uncertainty_Available` that every payload has."""

    covariance: list[list[float]]
    """Covariance of the shared parameters: one row per label, symmetric."""

    dof: int
    """Residuals minus estimated parameters."""

    labels: list[str]
    """Labels of the shared parameters, in the order of `covariance`."""

    noise: list[ResidualNoise]
    """The noise level of each kind of residual, estimated from the
    residuals at the solution.
    """

    num_residuals: int
    """Number of scalar residuals, priors included."""

    status: Literal["available"]


class Uncertainty_Available(_Uncertainty_AvailableRequired, total=False):
    """The covariance of the estimated parameters."""

    fixed: list[str]
    """Labels of the parameters held fixed. The covariance is conditional on
    them.
    """

    views: list[ViewCovariance]
    """Per-view parameters, one block per view that has free ones."""


class Uncertainty_Unavailable(TypedDict):
    """No covariance, for the reason given."""

    reason: UncertaintyUnavailable
    """Why the covariance is not available."""

    status: Literal["unavailable"]


Uncertainty: TypeAlias = Uncertainty_Available | Uncertainty_Unavailable
"""The uncertainty of a result's estimated parameters."""


class UncertaintyUnavailable_AtBound(TypedDict):
    """These parameters ended on a bound, where a Gaussian covariance does
    not describe them.
    """

    kind: Literal["at_bound"]
    labels: list[str]
    """Labels of the parameters on a bound."""


class UncertaintyUnavailable_NoRedundancy(TypedDict):
    """No more observations than estimated parameters."""

    kind: Literal["no_redundancy"]


class UncertaintyUnavailable_NotComputed(TypedDict):
    """The result was produced or stored without uncertainty."""

    kind: Literal["not_computed"]


class UncertaintyUnavailable_NotConverged(TypedDict):
    """The solve stopped on its iteration budget, short of a minimum."""

    kind: Literal["not_converged"]


class UncertaintyUnavailable_RankDeficient(TypedDict):
    """The data does not determine these parameters (or combinations of
    them): too few or too similar views, or a free gauge.
    """

    kind: Literal["rank_deficient"]
    unobservable: list[str]
    """Labels of the parameters involved."""


UncertaintyUnavailable: TypeAlias = (
    UncertaintyUnavailable_NotConverged
    | UncertaintyUnavailable_RankDeficient
    | UncertaintyUnavailable_AtBound
    | UncertaintyUnavailable_NoRedundancy
    | UncertaintyUnavailable_NotComputed
)
"""Why a result has no covariance."""


Unit: TypeAlias = Literal["pixel", "fraction", "ratio", "sigma", "correlation"]
"""The unit of a measured value.

- ``"pixel"``: Pixels.
- ``"fraction"``: A share in `[0, 1]`.
- ``"ratio"``: A dimensionless ratio, such as σ̂²/σ₀².
- ``"sigma"``: Multiples of the estimated noise level σ̂.
- ``"correlation"``: An absolute correlation coefficient in `[0, 1]`.
"""


Verdict: TypeAlias = Literal["pass", "warn", "fail"]
"""The judgment of a result, or of one check.

Ordered by severity: `Pass < Warn < Fail`.

- ``"pass"``: Nothing found that limits the result.
- ``"warn"``: Usable, with a weakness worth knowing; the message says which.
- ``"fail"``: The data does not support the result.
"""


class ViewCovariance(TypedDict):
    """The covariance of one view's own parameters."""

    covariance: list[list[float]]
    """Their covariance: one row per label, symmetric."""

    labels: list[str]
    """Labels of the view's parameters, e.g. `camera_se3_target.rx`."""

    view: int
    """View index, as in the result's per-view lists."""


